package cn.gov.document.platform.knowledge.application;

import cn.gov.document.platform.common.file.DocxSecurityValidator;

import cn.gov.document.platform.common.context.RequestContext;import cn.gov.document.platform.common.error.BusinessException;import cn.gov.document.platform.knowledge.api.KnowledgeDtos;import cn.gov.document.platform.knowledge.domain.*;import cn.gov.document.platform.knowledge.persistence.*;import com.baomidou.mybatisplus.core.conditions.query.LambdaQueryWrapper;import org.apache.pdfbox.Loader;import org.apache.pdfbox.text.PDFTextStripper;import org.apache.poi.xwpf.usermodel.XWPFDocument;import org.springframework.security.core.Authentication;import org.springframework.security.core.context.SecurityContextHolder;import org.springframework.stereotype.Service;import org.springframework.transaction.annotation.Transactional;import org.springframework.util.StringUtils;import org.springframework.web.multipart.MultipartFile;
import java.io.*;import java.nio.charset.StandardCharsets;import java.security.*;import java.time.*;import java.util.*;import java.util.stream.Collectors;

@Service public class KnowledgeService{
    private static final int MAX_FILE_SIZE=20*1024*1024,CHUNK_SIZE=500,OVERLAP=50;
    private final KnowledgeSourceMapper sourceMapper;private final KnowledgeDocumentMapper documentMapper;private final KnowledgeChunkMapper chunkMapper;private final KnowledgeFileStore fileStore;
    public KnowledgeService(KnowledgeSourceMapper sourceMapper,KnowledgeDocumentMapper documentMapper,KnowledgeChunkMapper chunkMapper,KnowledgeFileStore fileStore){this.sourceMapper=sourceMapper;this.documentMapper=documentMapper;this.chunkMapper=chunkMapper;this.fileStore=fileStore;}
    @Transactional public KnowledgeDtos.SourceResponse createSource(KnowledgeDtos.CreateSourceRequest request){if(sourceMapper.selectCount(new LambdaQueryWrapper<KnowledgeSourceEntity>().eq(KnowledgeSourceEntity::getSourceCode,request.sourceCode().trim()))>0)throw BusinessException.conflict("知识库代码已存在");if(request.storageType().contains("向量")&&(!StringUtils.hasText(request.vectorModel())||request.vectorDimensions()==null))throw BusinessException.unprocessable("向量或混合知识库必须配置向量模型和维度");KnowledgeSourceEntity e=new KnowledgeSourceEntity();e.setTenantId(RequestContext.tenantId());e.setSourceCode(request.sourceCode().trim());e.setSourceName(request.sourceName().trim());e.setCategory(request.category());e.setStorageType(request.storageType());e.setVectorModel(request.vectorModel());e.setVectorDimensions(request.vectorDimensions());e.setPermissionScope(request.permissionScope());e.setEntryCount(0);e.setIsActive(true);sourceMapper.insert(e);return KnowledgeDtos.SourceResponse.from(e);}
    public List<KnowledgeDtos.SourceResponse> sources(){return sourceMapper.selectList(new LambdaQueryWrapper<KnowledgeSourceEntity>().orderByAsc(KnowledgeSourceEntity::getSourceName)).stream().map(KnowledgeDtos.SourceResponse::from).toList();}
    public List<KnowledgeDtos.DocumentResponse> documents(String sourceId){requireSource(sourceId);return documentMapper.selectList(new LambdaQueryWrapper<KnowledgeDocumentEntity>().eq(KnowledgeDocumentEntity::getSourceId,sourceId).orderByDesc(KnowledgeDocumentEntity::getUpdatedAt)).stream().map(KnowledgeDtos.DocumentResponse::from).toList();}
    @Transactional public KnowledgeDtos.DocumentResponse upload(String sourceId,MultipartFile file,String title,String metadata,String authority,LocalDate effective,LocalDate expiry,String permission){KnowledgeSourceEntity source=requireSource(sourceId);if(file==null||file.isEmpty())throw BusinessException.unprocessable("请选择知识文档");if(file.getSize()>MAX_FILE_SIZE)throw BusinessException.unprocessable("知识文档不得超过 20MB");if(effective!=null&&expiry!=null&&expiry.isBefore(effective))throw BusinessException.unprocessable("失效日期不得早于生效日期");byte[] bytes;try{bytes=file.getBytes();}catch(IOException e){throw BusinessException.unprocessable("知识文档读取失败");}String hash=sha256(bytes);if(documentMapper.selectCount(new LambdaQueryWrapper<KnowledgeDocumentEntity>().eq(KnowledgeDocumentEntity::getSourceId,sourceId).eq(KnowledgeDocumentEntity::getOriginalFileHash,hash))>0)throw BusinessException.conflict("同一知识库中已存在相同文件");String filename=Optional.ofNullable(file.getOriginalFilename()).orElse("document.txt");String extracted=extract(filename,bytes);if(!StringUtils.hasText(extracted))throw BusinessException.unprocessable("文档未提取到可检索文本，扫描件请先完成 OCR");KnowledgeDocumentEntity e=new KnowledgeDocumentEntity();e.setId(UUID.randomUUID().toString().replace("-",""));e.setTenantId(RequestContext.tenantId());e.setSourceId(sourceId);e.setDocumentTitle(StringUtils.hasText(title)?title.trim():filename);e.setOriginalFilePath(fileStore.write(sourceId,e.getId(),filename,bytes));e.setOriginalFileHash(hash);e.setParsedStatus("待解析");e.setMetadata(StringUtils.hasText(metadata)?metadata:"{}");e.setAuthorityLevel(StringUtils.hasText(authority)?authority:"一般资料");e.setEffectiveDate(effective);e.setExpiryDate(expiry);e.setPermissionLevel(StringUtils.hasText(permission)?permission:"内部");e.setChunkCount(0);e.setDocumentVersion(1);e.setExtractedText(extracted);documentMapper.insert(e);source.setEntryCount(source.getEntryCount()+1);source.setLastSyncTime(OffsetDateTime.now());sourceMapper.updateById(source);return KnowledgeDtos.DocumentResponse.from(e);}
    @Transactional public KnowledgeDtos.ParseResponse parse(String sourceId,String documentId){requireSource(sourceId);KnowledgeDocumentEntity document=requireDocument(sourceId,documentId);if("已完成".equals(document.getParsedStatus()))return new KnowledgeDtos.ParseResponse(documentId,"已完成",document.getChunkCount(),List.of("文档已解析，本次未重复切分"));chunkMapper.delete(new LambdaQueryWrapper<KnowledgeChunkEntity>().eq(KnowledgeChunkEntity::getDocumentId,documentId));String text=document.getExtractedText().replace("\r\n","\n").replaceAll("[ \\t]+"," ").trim();int order=1,start=0;while(start<text.length()){int end=Math.min(text.length(),start+CHUNK_SIZE);if(end<text.length()){int boundary=Math.max(text.lastIndexOf('。',end),text.lastIndexOf('\n',end));if(boundary>start+CHUNK_SIZE/2)end=boundary+1;}String value=text.substring(start,end).trim();if(!value.isEmpty()){KnowledgeChunkEntity chunk=new KnowledgeChunkEntity();chunk.setTenantId(RequestContext.tenantId());chunk.setDocumentId(documentId);chunk.setChunkOrder(order++);chunk.setChunkText(value);chunk.setChunkTextHash(sha256(value.getBytes(StandardCharsets.UTF_8)));chunk.setKeywords("[]");chunk.setStartPosition(start);chunk.setEndPosition(end);chunkMapper.insert(chunk);}if(end>=text.length())break;start=Math.max(start+1,end-OVERLAP);}document.setChunkCount(order-1);document.setParsedStatus("已完成");documentMapper.updateById(document);return new KnowledgeDtos.ParseResponse(documentId,"已完成",document.getChunkCount(),List.of());}
    public List<KnowledgeDtos.SearchResponse> search(String query,String sourceId,int limit){if(!StringUtils.hasText(query)||query.trim().length()<2)throw BusinessException.unprocessable("检索词至少 2 个字符");int safeLimit=Math.min(50,Math.max(1,limit));LocalDate today=LocalDate.now();List<KnowledgeSourceEntity> sources=sourceMapper.selectList(new LambdaQueryWrapper<KnowledgeSourceEntity>().eq(KnowledgeSourceEntity::getIsActive,true).eq(StringUtils.hasText(sourceId),KnowledgeSourceEntity::getId,sourceId));Map<String,KnowledgeSourceEntity> sourceMap=sources.stream().collect(Collectors.toMap(KnowledgeSourceEntity::getId,s->s));if(sourceMap.isEmpty())return List.of();int clearance=clearance();List<KnowledgeDocumentEntity> allowed=documentMapper.selectList(new LambdaQueryWrapper<KnowledgeDocumentEntity>().in(KnowledgeDocumentEntity::getSourceId,sourceMap.keySet()).eq(KnowledgeDocumentEntity::getParsedStatus,"已完成")).stream().filter(d->rank(d.getPermissionLevel())<=clearance).filter(d->(d.getEffectiveDate()==null||!d.getEffectiveDate().isAfter(today))&&(d.getExpiryDate()==null||!d.getExpiryDate().isBefore(today))).toList();if(allowed.isEmpty())return List.of();Map<String,KnowledgeDocumentEntity> docs=allowed.stream().collect(Collectors.toMap(KnowledgeDocumentEntity::getId,d->d));String keyword=query.trim();return chunkMapper.selectList(new LambdaQueryWrapper<KnowledgeChunkEntity>().in(KnowledgeChunkEntity::getDocumentId,docs.keySet()).like(KnowledgeChunkEntity::getChunkText,keyword)).stream().map(chunk->{KnowledgeDocumentEntity d=docs.get(chunk.getDocumentId());KnowledgeSourceEntity s=sourceMap.get(d.getSourceId());int occurrences=occurrences(chunk.getChunkText(),keyword);double score=Math.min(1.0,0.55+occurrences*0.1+(d.getDocumentTitle().contains(keyword)?0.15:0));return new KnowledgeDtos.SearchResponse(s.getId(),s.getSourceName(),d.getId(),d.getDocumentTitle(),chunk.getId(),chunk.getChunkOrder(),snippet(chunk.getChunkText(),keyword),d.getAuthorityLevel(),d.getPermissionLevel(),score,d.getOriginalFileHash());}).sorted(Comparator.comparingDouble(KnowledgeDtos.SearchResponse::score).reversed()).limit(safeLimit).toList();}
    private String extract(String filename,byte[] bytes){String lower=filename.toLowerCase(Locale.ROOT);try{if(lower.endsWith(".txt")||lower.endsWith(".md")||lower.endsWith(".csv"))return new String(bytes,StandardCharsets.UTF_8).replaceFirst("^\\uFEFF","");if(lower.endsWith(".docx")){DocxSecurityValidator.validate(filename,bytes,20L*1024*1024,"知识文档");try(XWPFDocument doc=new XWPFDocument(new ByteArrayInputStream(bytes))){return doc.getParagraphs().stream().map(p->p.getText()).collect(Collectors.joining("\n"));}}if(lower.endsWith(".pdf")){try(var pdf=Loader.loadPDF(bytes)){return new PDFTextStripper().getText(pdf);}}throw BusinessException.unprocessable("仅支持 TXT、Markdown、CSV、DOCX 和可提取文本的 PDF");}catch(IOException|RuntimeException e){if(e instanceof BusinessException b)throw b;throw BusinessException.unprocessable("知识文档解析失败或文件已损坏");}}
    private int clearance(){Authentication a=SecurityContextHolder.getContext().getAuthentication();if(a!=null&&a.getAuthorities().stream().anyMatch(v->"ROLE_platform.admin".equals(v.getAuthority())))return 3;if(a!=null&&a.getAuthorities().stream().anyMatch(v->"ROLE_platform.reviewer".equals(v.getAuthority())))return 2;return 1;}private int rank(String level){return switch(level==null?"内部":level){case"公开"->0;case"内部"->1;case"秘密"->2;case"机密"->3;default->3;};}
    private int occurrences(String text,String key){int count=0,from=0;while((from=text.indexOf(key,from))>=0){count++;from+=key.length();}return count;}private String snippet(String text,String key){int at=Math.max(0,text.indexOf(key));int start=Math.max(0,at-80),end=Math.min(text.length(),at+key.length()+120);return(start>0?"…":"")+text.substring(start,end)+(end<text.length()?"…":"");}
    private KnowledgeSourceEntity requireSource(String id){KnowledgeSourceEntity e=sourceMapper.selectById(id);if(e==null)throw BusinessException.notFound("知识库不存在");return e;}private KnowledgeDocumentEntity requireDocument(String sourceId,String id){KnowledgeDocumentEntity e=documentMapper.selectById(id);if(e==null||!sourceId.equals(e.getSourceId()))throw BusinessException.notFound("知识文档不存在");return e;}
    private String sha256(byte[] value){try{return HexFormat.of().formatHex(MessageDigest.getInstance("SHA-256").digest(value));}catch(NoSuchAlgorithmException e){throw new IllegalStateException(e);}}
}
